// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2024, "8-9", [{"author":"Е. Муравенко","question":"Вставьте пропущенный устойчивый оборот в четверостишие Андрея Усачёва:\n<em>Ходит нынче на природу\nПро́пасть всякого народу:\nРыбаков __________,\nА червя пойди найди!</em>","choices":["<em>сюда веди</em>","<em>хоть мух плоди</em>","<em>хоть пруд пруди</em>","<em>не подводи</em>","<em>уж приведи</em>."],"key":"В","review":["На рыбалке","В последней строке автор жалуется, что червя для рыбалки трудно найти. Перед ней должно стоять выражение о том, что рыбаков очень много.","«Хоть пруд пруди» означает «очень много». Этот устойчивый оборот подходит по смыслу и рифмуется с «найди»."]},{"author":"И. Иткин","question":"Какое слово не однокоренное остальным?","choices":["<em>клон</em>","<em>склон</em>","<em>наклон</em>","<em>преклонение</em>","все эти слова однокоренные."],"key":"А","review":["Корень и значение","«Склон», «наклон» и «преклонение» связаны со словом «клониться»: их значения относятся к наклону или движению вниз.","«Клон» — отдельное заимствованное слово. Так называют генетическую копию организма. Его сходство с корнем «клон-» в остальных словах случайно."]},{"author":"А. Остроумова","question":"В каком примере словосочетания соотносятся по смыслу не так, как в остальных?","choices":["<em>первый посетитель — последний посетитель</em>","<em>первая встреча — последняя встреча</em>","<em>первая попытка — последняя попытка</em>","<em>первый негодяй — последний негодяй</em>","<em>первый вопрос — последний вопрос</em>."],"key":"Г","review":["Первый и последний","Посетителей, встречи, попытки и вопросы можно расположить в порядке следования. Тогда «первый» и «последний» указывают на разные концы этого порядка.","«Первый негодяй» и «последний негодяй» оба могут означать «отъявленный негодяй». В этом примере порядковые слова служат оценкой."]},{"author":"Л. Фёдорова","question":"Из какого глагола нельзя получить новый глагол добавлением приставки <em>по-</em>?","choices":["<em>ставить</em>","<em>резать</em>","<em>расти</em>","<em>читать</em>","<em>класть</em>."],"key":"Д","review":["Приставка «по-»","Добавь приставку к каждой форме. В литературном языке употребляются «поставить», «порезать», «порасти» и «почитать».","Для «класть» в значении завершённого действия употребляют «положить». Приставка меняет и основу. Формы «покласть» в литературной норме нет."]},{"author":"А. Сомин и Ф. Тучак","question":"В людиковском наречии карельского языка есть много заимствований из русского. Одно из них — слово igruška, которое сейчас обозначает игрушку или куклу. Но, когда оно было заимствовано, оно значило _____.","choices":["‘трактор’","‘колыбель’","‘гармонь’","‘ведро’","‘плавленый сырок’."],"key":"В","review":["Слово в карельском наречии","Ищи значение, которое могло возникнуть из русского «играть». В игру можно играть с игрушкой, а на музыкальном инструменте — исполнять мелодии.","Из предложенных предметов музыкальный инструмент — гармонь. В таком значении слово и пришло в людиковское наречие, а позднее стало названием игрушки вообще."]},{"author":"Б. Иомдин","question":"Даны пять сочетаний с предлогом <em>под</em>. Автоматический переводчик в каждом из них обычно переводит предлог на английский язык одинаково, но в одном случае на самом деле лучше использовать другой предлог. В каком? (Знание английского языка для решения задачи не требуется.)","choices":["<em>под деревом</em>","<em>под столом</em>","<em>под телевизором</em>","<em>под Москвой</em>","под Эйфелевой башней."],"key":"Г","review":["Что значит «под»","Под деревом, столом, телевизором и башней что-то находится ниже соответствующего предмета.","«Под Москвой» значит «вблизи Москвы», на прилегающей территории. Это пространственное отношение передаётся как «рядом», а не как «ниже»."]},{"author":"А. Пиперски","question":"Древнерусская <em>пясть</em> — это часть _____.","choices":["головы","шеи","руки","ноги","желудка."],"key":"В","review":["Древнее название части тела","В современной анатомии есть слово «пясть». Также употребляют прилагательное «пястный», например «пястные кости».","Пясть — часть кисти между запястьем и пальцами. Следовательно, речь о руке."]},{"author":"И. Рубанов","question":"<em>Оля чаёвничает</em>. Чем занимается Оля?","choices":["выращивает чай","заваривает чай","расфасовывает чай","продаёт чай","пьёт чай."],"key":"Д","review":["Глагол с корнем «чай»","В слове «чаёвничает» узнаётся «чай», но глагол описывает целое занятие. Сравни слово «чаепитие».","«Чаёвничать» значит пить чай, обычно не спеша. Заваривание может этому предшествовать, а цель действия — чаепитие."]},{"author":"О. Подлесская","question":"Испанская поговорка «De tal palo, tal astilla» буквально означает ‘какая палка, такая и щепка’. А какая русская пословица или поговорка соответствует ей?","choices":["<em>Лес рубят — щепки летят</em>.","<em>Яблочко от яблони недалеко падает</em>.","<em>Нашла коса на камень</em>.","<em>Сколько верёвочке ни виться, всё конец будет</em>.","<em>В своём глазу бревна не видишь</em>."],"key":"Б","review":["Палка и щепка","Щепка сделана из той же древесины, что и палка. Сравнение говорит о сходстве того, что получилось, с тем, от чего оно произошло.","В русской поговорке для той же мысли используют яблоко и яблоню. Говорят «Яблочко от яблони недалеко падает»."]},{"author":"П. Долгополов","question":"В какой паре слов ударение падает на разные по счёту слоги?","choices":["<em>некто — нечто</em>","<em>недруг — недуг</em>","<em>некуда — некогда</em>","<em>невежа — невежда</em>","<em>неискренний — неистовый</em>."],"key":"Б","review":["Слог под ударением","Произнеси «не́кто — не́что», «не́куда — не́когда», «неве́жа — неве́жда», «неи́скренний — неи́стовый». В каждой из этих пар ударения стоят на одинаковых по счёту слогах.","В паре «не́друг — неду́г» ударение сначала на первом слоге, а затем на втором."]},{"author":"М. Рубинштейн","question":"<em>Помарка</em>, <em>ремарка</em>, <em>маркий</em>, <em>маркер</em>. Какие из этих слов — однокоренные с глаголом <em>марать</em>, т. е. ‘пачкать’?","choices":["<em>маркий</em> и <em>маркер</em>","<em>помарка</em> и <em>ремарка</em>","<em>помарка</em> и <em>маркий</em>","все","ни одно."],"key":"В","review":["Слова от «марать»","«Маркий» — такой, который легко испачкать. «Помарка» — ошибочная черта или исправление на бумаге, буквально след от того, что замарали написанное.","«Ремарка» — замечание, «маркер» — средство для отметки. Эти заимствованные слова с русским «марать» не однокоренные."]},{"author":"О. Подлесская","question":"«Нам надо подготовить выступление к празднику, а у нас ещё __________».","choices":["конь не валялся","собака не зарыта","цыплята не посчитаны","вороны не посчитаны","рак не свистнул."],"key":"А","review":["Выступление к празднику","Говорящий жалуется, что задача ещё даже не начата. Нужен устойчивый оборот с таким смыслом.","«Ещё конь не валялся» говорят, когда к работе не приступали. Другие варианты образованы из слов знакомых выражений с другими значениями."]},{"author":"А. Пиперски","question":"Какое максимальное количество слогов может содержать в себе числительное в именительном падеже, которое называет целое число от 1 до 100?","choices":["5","6","7","8","9."],"key":"В","review":["Слоги в числительном","Посчитай слоги по гласным. Числительные от 21 до 99 складываются из десятков и единиц. В названии десятков не больше четырёх слогов, в названии единиц — не больше трёх.","«Восемьдесят четыре» даёт четыре плюс три, то есть семь слогов. У числительных до двадцати и у слова «сто» слогов меньше, поэтому семь — максимум."]},{"author":"Л. Фёдорова","question":"В одной китайской легенде мастер-оружейник уверял, что <em>его копьё пробьёт любой щит, но его щит не пробьёт ни одно копьё.</em> Назовите по порядку падежи существительных в выделенном фрагменте.","choices":["Им., В., Им., В.","В., Им., В., Им.","Им., В., В., Им.","В., Им., Им., В.","Им., В., В., В."],"key":"В","review":["Копьё и щит","В первой части копьё выполняет действие, а щит испытывает его. Получаем именительный и винительный падежи.","Во второй части слова поменялись ролями в порядке перечисления: «его щит» — дополнение, «ни одно копьё» — подлежащее. Получаем именительный, винительный, винительный, именительный."]},{"author":"О. Подлесская","question":"Какое название десерта исторически буквально означает ‘дважды приготовленный’?","choices":["<em>марципан</em>","<em>драже</em>","<em>желе</em>","<em>безе</em>","бисквит."],"key":"Д","review":["Дважды приготовленный десерт","Для разгадки ищи в старом названии часть, которая значит «дважды». В слове «бисквит» это начальное «бис-».","Французское «biscuit» исторически складывается из слов со значениями «дважды» и «приготовленный, испечённый». Так называли изделие, которое повторно подсушивали при выпечке."]},{"author":"М. Рубинштейн","question":"В каком из следующих отрывков слово <em>да</em> наверняка употреблено не так, как в остальных?","choices":["<em>Да простят нас фанатики этого вида спорта, но дело обстоит именно так.</em> («Знание-сила»)","<em>И да отсохнут мои ноги, если ты не станешь президентом!</em> (Алесь Пашкевич)","<em>Господи, охрани батюшку от беды, и да выйдет он невредимым из этой схватки.</em> (Зоя Масленикова)","<em>А герой… Да проживёт как-нибудь!</em> («Известия»)","<em>Кто сказал тебе, что нет на свете настоящей, верной, вечной любви? Да отрежут лгуну его гнусный язык!</em> (Михаил Булгаков)"],"key":"Г","review":["Частица «да»","В четырёх отрывках с частицей можно сказать «пусть»: пусть простят, пусть отсохнут, пусть выйдет, пусть отрежут. Это пожелания или призывы.","«Да проживёт как-нибудь» сказано уверенно, как «ну конечно, проживёт». Здесь частица усиливает утверждение."]},{"author":"А. Остроумова","question":"В рассказе «Степь» А. П. Чехова читаем: «Кирюха жил в _____ у хороших людей и на весь округ считался лучшим троечником». Вставьте пропущенное слово.","choices":["кузнецах","учителях","кучерах","лекарях","студентах."],"key":"В","review":["Троечник у Чехова","Слово «троечник» бывает связано не с оценкой, а с тройкой лошадей. В рассказе Кирюхой восхищаются как опытным возницей.","На тройке ездит кучер. В старом выражении «жил в кучерах» имеется в виду «служил кучером»."]},{"author":"Л. Фёдорова","question":"<em>Смех</em>, <em>сон</em>, <em>рука</em>, <em>болезнь</em>. От всех этих слов можно образовать сложные слова с одним и тем же вторым корнем. Какое ещё слово можно добавить в этот список?","choices":["<em>стон</em>","<em>стих</em>","<em>голова</em>","<em>здоровье</em>","<em>толпа</em>."],"key":"Б","review":["Второй корень сложного слова","От слов из условия получаются «смехотворный», «снотворный», «рукотворный», «болезнетворный». Повторяется корень «твор-».","От слова «стих» можно образовать «стихотворение» или «стихотворный». В них тот же второй корень."]},{"author":"И. Иткин","question":"Все приведённые ниже слова, кроме одного, можно рассматривать как образованные с помощью одного и того же чередования звуков. Кроме какого?","choices":["<em>богач</em>","<em>бородач</em>","<em>лихач</em>","<em>лохмач</em>","<em>усач</em>."],"key":"В","review":["Как чередуются Т и Ч","Возьми прилагательные «богатый», «бородатый», «лохматый» и «усатый». При образовании названий людей «богач», «бородач», «лохмач» и «усач» Т меняется на Ч.","«Лихач» связано с «лихой». В исходной основе нет Т, поэтому общего чередования здесь нет."]},{"author":"Ф. Тучак","question":"Филипп читал текст про рыцарскую экипировку и запустил поиск по слову, чтобы найти нужный фрагмент. Формы какого глагола ему также попались среди результатов?","choices":["<em>получить</em>","<em>отнять</em>","<em>взять</em>","<em>купить</em>","забрать."],"key":"Д","review":["Слово в рыцарской истории","Забрало — откидывающаяся часть рыцарского шлема, которая закрывает лицо. По такому слову можно искать нужный фрагмент об экипировке.","Написание «забрало» совпадает с формой прошедшего времени глагола «забрать», например «течение забрало лодку». Поиск по буквам мог найти обе формы."]},{"author":"Б. Иомдин","question":"Слово <em>радушие</em> образовано не совсем обычным образом. У какого слова, по-видимому, похожая история?","choices":["<em>рукомойник</em>","<em>бредятина</em>","<em>холодрыга</em>","<em>бандюга</em>","<em>забегаловка</em>."],"key":"В","review":["Один звук у двух основ","В слове «радушие» одна Д подходит к концу «рад» и к началу «душа». Две части накладываются друг на друга в одной букве.","Похожее наложение получается у «холодрыги». Конечное Д слова «холод» совпадает с начальным Д в «дрыгать»."]},{"author":"Б. Иомдин","question":"Вот две строки из поэмы Константина Симонова «Первая любовь»:\n<em>Пиджак, зашитый грубыми _____,\nТетрадка с юношескими _____.</em>\nПропущенные слова звучат совершенно одинаково. А что различается в их написании?","choices":["одна гласная","одна согласная","одна гласная и одна согласная","две гласных","две согласных."],"key":"В","review":["Слова, звучащие одинаково","Швы на пиджаке сделаны «стежками», а в тетрадке записаны юношеские «стишки», поэтому нужно «стишками».","Безударные Е и И здесь совпадают в произношении. Ж перед глухим К оглушается до Ш. На письме различаются одна гласная и одна согласная."]},{"author":"А. Сомин","question":"Болгарский язык — близкий родственник русского. В переводе на русский язык болгарского существительного <em>двубой</em> есть сочетание __.","choices":["<em>уя</em>","<em>уэ</em>","<em>оа</em>","<em>юо</em>","ау."],"key":"Б","review":["Ссора двоих по-болгарски","В болгарском «двубой» слышатся «два» и «бой». Такой бой между двумя людьми можно назвать поединком.","Другое русское название — «дуэль». В нём подряд стоят У и Э."]},{"author":"Л. Фёдорова","question":"<em>Прекрасное далёко, не будь ко мне жестоко!</em> Сколько членов предложения содержится в этой фразе из песни на слова Юрия Энтина к фильму «Гостья из будущего»?","choices":["5","4","3","2","1."],"key":"Г","review":["Члены предложения","«Прекрасное далёко» — обращение. Оно называет того, к кому направлена просьба, и не является членом предложения.","«Не будь жестоко» — составное сказуемое, «ко мне» — дополнение. Получается два члена предложения."]},{"author":"А. Остроумова","question":"В этом шуточном определении мы пропустили два исторически однокоренных слова: «_____ человек — это человек, который сломал _____, когда ему обещали провести центральное отопление». Какая приставка в прилагательном на месте первого пропуска?","choices":["<em>бес-</em>","<em>на-</em>","<em>под-</em>","<em>по-</em>","<em>с-</em>."],"key":"А","review":["Шутка об отоплении","После обещания центрального отопления герой сломал печь. В шуточном определении его можно назвать «беспечным», буквально оставшимся без печи.","«Беспечный» обычно значит «беззаботный». В слове выделяется приставка «бес-», поскольку за ней стоит глухая П."]},{"author":"Е. Муравенко","question":"Даны названия лиц мужского пола с суффиксом <em>-ец</em>: <em>беглец</em>, <em>незнакомец</em>, <em>однофамилец</em>, <em>пловец</em>, <em>продавец</em>, <em>счастливец</em>, <em>торговец</em>. В каждом слове замените суффикс <em>-ец</em> на другой суффикс для образования соответствующего названия лица женского пола. Сколько разных возможностей вы использовали?","choices":["семь","шесть","пять","четыре","две."],"key":"В","review":["Суффиксы названий женщин","Запиши пары: беглец — беглянка, незнакомец — незнакомка, однофамилец — однофамилица, пловец — пловчиха, продавец — продавщица, счастливец — счастливица, торговец — торговка.","Дважды получаются суффиксы «-к-» и «-иц-». Беглянка, пловчиха и продавщица дают ещё три разных способа. Всего пять."]},{"author":"Е. Муравенко и Е. Пименова","question":"В одной телепередаче рассказывалось о большой популярности английского фарфора и, переводя слова английского специалиста, переводчик сказал, что «фарфор рассылается <strong>во все четыре уголка земного шара</strong>». Какими словами надо заменить выделенные слова?","choices":["во все четыре части света","на все четыре материка","на все четыре стороны","ничего исправлять не надо: всё верно","ни один из вариантов (А)–(Г) не годится."],"key":"Д","review":["Фарфор по всему свету","Слова «во все четыре уголка» соединяют число из выражения «на все четыре стороны» с другим оборотом, «во все уголки земного шара».","Фразу можно исправить, убрав «четыре», или сказать «по всему свету». Ни одного из этих вариантов в списке нет."]},{"author":"Е. Пискунова","question":"Герою повести Владислава Крапивина, воспитаннику детского дома, очень не нравится его имя. Мальчик считает, что принтер случайно напечатал в первой букве его имени лишнее колечко. Воспитательница возражает, что этого не может быть, потому что в документах имена пишутся полностью. Какую букву в какую превратил принтер, по мнению мальчика?","choices":["Б в В","Г в Б","Р в В","Р в Ф","К в не очень аккуратное Ю."],"key":"Г","review":["Колечко в букве","Представь, что принтер оставил все штрихи правильной буквы и добавил слева ещё одну петлю. У Р есть вертикаль и петля справа.","С дополнительной петлёй получается Ф. Герой мог счесть «Фома» испорченным именем «Рома», а воспитательница напомнила, что полное имя было бы «Роман»."]},{"author":"А. Пиперски","question":"Дан список окончаний: -<em>е</em>, -<em>ом</em>, -<em>и</em>, -<em>а</em>. Какие из них встречаются в предложном падеже единственного числа у существительных мужского рода?","choices":["только -<em>е</em>","только -<em>е</em> и -<em>ом</em>","только -<em>е</em> и -<em>и</em>","только -<em>е</em>, -<em>ом</em> и -<em>и</em>","все."],"key":"Г","review":["Окончания в предложном","Поставь разные существительные мужского рода после «о». Получатся «о столе» с «-е», «о знакомом» с «-ом» и «о гении» с «-и».","Первые три окончания встречаются. «-а» может быть, например, в родительном падеже («нет стола»), а в предложном его нет."]},{"author":"Б. Иомдин","question":"<em>Пожимаем плечами или цинично усмехаемся, а __________ другое сразу</em> (Т. Харфорд, пер. Е. Л. Левиной). На месте прочерка пропущены четыре слова. Если заменить их буквами, то как будет выглядеть пропущенный фрагмент?","choices":["A A A A","A Б A Б","A A A Б","A Б Б A","A A Б Б."],"key":"Б","review":["Два действия сразу","Пожать плечами и усмехнуться можно по отдельности либо сделать то и другое сразу. В цитате оба действия названы вместе.","Получается «а то и то и другое сразу». В пропуске «то и то и», поэтому повторяется последовательность А Б А Б."]}], {"year":2024,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2024-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
